import{_ as a,o as l,c as d,a2 as i}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"终端用户管理","description":"","frontmatter":{},"headers":[],"relativePath":"developer/app-user.md","filePath":"developer/app-user.md"}'),r={name:"developer/app-user.md"};function e(o,t,h,n,s,c){return l(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="终端用户管理" tabindex="-1">终端用户管理 <a class="header-anchor" href="#终端用户管理" aria-label="Permalink to &quot;终端用户管理&quot;">​</a></h1><p>终端用户是使用您应用的最终用户，您可以在这里管理所有用户账号。</p><h2 id="功能列表" tabindex="-1">功能列表 <a class="header-anchor" href="#功能列表" aria-label="Permalink to &quot;功能列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>查看用户列表</td><td>查看所有注册用户</td></tr><tr><td>创建用户</td><td>手动创建用户账号</td></tr><tr><td>编辑用户</td><td>修改用户信息</td></tr><tr><td>删除用户</td><td>删除用户账号</td></tr><tr><td>封禁/解封</td><td>封禁或解封用户</td></tr><tr><td>重置密码</td><td>重置用户密码</td></tr><tr><td>延长会员</td><td>延长用户会员时长</td></tr><tr><td>查看设备</td><td>查看用户绑定的设备</td></tr><tr><td>强制下线</td><td>强制用户下线</td></tr></tbody></table><h2 id="用户列表" tabindex="-1">用户列表 <a class="header-anchor" href="#用户列表" aria-label="Permalink to &quot;用户列表&quot;">​</a></h2><h3 id="查看用户" tabindex="-1">查看用户 <a class="header-anchor" href="#查看用户" aria-label="Permalink to &quot;查看用户&quot;">​</a></h3><ol><li>登录开发者后台</li><li>点击左侧菜单「应用管理」→「终端用户管理」</li></ol><h3 id="列表字段" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段" aria-label="Permalink to &quot;列表字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>用户名</td><td>用户的登录名</td></tr><tr><td>昵称</td><td>用户的显示名</td></tr><tr><td>邮箱</td><td>用户的邮箱</td></tr><tr><td>手机号</td><td>用户的手机号</td></tr><tr><td>所属应用</td><td>用户所属的应用</td></tr><tr><td>绑定设备</td><td>用户绑定的设备数量</td></tr><tr><td>封禁状态</td><td>是否被封禁</td></tr><tr><td>会员状态</td><td>会员是否有效</td></tr><tr><td>WS 在线</td><td>是否在线</td></tr><tr><td>登录次数</td><td>累计登录次数</td></tr><tr><td>最后登录</td><td>最后登录时间</td></tr></tbody></table><h3 id="筛选和搜索" tabindex="-1">筛选和搜索 <a class="header-anchor" href="#筛选和搜索" aria-label="Permalink to &quot;筛选和搜索&quot;">​</a></h3><p>支持按以下条件筛选：</p><ul><li>用户名</li><li>邮箱</li><li>手机号</li><li>封禁状态</li><li>会员状态</li><li>在线状态</li></ul><h2 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to &quot;创建用户&quot;">​</a></h2><h3 id="步骤-1-点击创建" tabindex="-1">步骤 1：点击创建 <a class="header-anchor" href="#步骤-1-点击创建" aria-label="Permalink to &quot;步骤 1：点击创建&quot;">​</a></h3><ol><li>在用户列表页面</li><li>点击「创建」按钮</li></ol><h3 id="步骤-2-填写信息" tabindex="-1">步骤 2：填写信息 <a class="header-anchor" href="#步骤-2-填写信息" aria-label="Permalink to &quot;步骤 2：填写信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>必填</th></tr></thead><tbody><tr><td>所属应用</td><td>选择应用</td><td>✅</td></tr><tr><td>用户名</td><td>3-20 个字符</td><td>✅</td></tr><tr><td>密码</td><td>至少 6 位</td><td>✅</td></tr><tr><td>邮箱</td><td>有效邮箱地址</td><td>❌</td></tr><tr><td>手机号</td><td>有效手机号</td><td>❌</td></tr><tr><td>昵称</td><td>用户显示名</td><td>❌</td></tr><tr><td>会员到期</td><td>设置会员到期时间</td><td>❌</td></tr></tbody></table><h3 id="步骤-3-确认创建" tabindex="-1">步骤 3：确认创建 <a class="header-anchor" href="#步骤-3-确认创建" aria-label="Permalink to &quot;步骤 3：确认创建&quot;">​</a></h3><ol><li>点击「确定」按钮</li><li>用户创建成功</li></ol><h2 id="用户操作" tabindex="-1">用户操作 <a class="header-anchor" href="#用户操作" aria-label="Permalink to &quot;用户操作&quot;">​</a></h2><h3 id="封禁用户" tabindex="-1">封禁用户 <a class="header-anchor" href="#封禁用户" aria-label="Permalink to &quot;封禁用户&quot;">​</a></h3><ol><li>在用户列表找到目标用户</li><li>点击操作列的「更多」按钮</li><li>选择「封禁」</li><li>确认封禁操作</li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>封禁后用户将无法登录和使用应用</p></div><h3 id="解封用户" tabindex="-1">解封用户 <a class="header-anchor" href="#解封用户" aria-label="Permalink to &quot;解封用户&quot;">​</a></h3><ol><li>在用户列表找到目标用户</li><li>点击操作列的「更多」按钮</li><li>选择「解封」</li><li>确认解封操作</li></ol><h3 id="重置密码" tabindex="-1">重置密码 <a class="header-anchor" href="#重置密码" aria-label="Permalink to &quot;重置密码&quot;">​</a></h3><ol><li>在用户列表找到目标用户</li><li>点击操作列的「更多」按钮</li><li>选择「重置密码」</li><li>输入新密码</li><li>确认重置</li></ol><h3 id="延长会员" tabindex="-1">延长会员 <a class="header-anchor" href="#延长会员" aria-label="Permalink to &quot;延长会员&quot;">​</a></h3><ol><li>在用户列表找到目标用户</li><li>点击操作列的「更多」按钮</li><li>选择「延长会员」</li><li>选择时间单位和数值</li><li>确认延长</li></ol><h3 id="查看设备" tabindex="-1">查看设备 <a class="header-anchor" href="#查看设备" aria-label="Permalink to &quot;查看设备&quot;">​</a></h3><ol><li>在用户列表找到目标用户</li><li>点击操作列的「更多」按钮</li><li>选择「查看设备」</li><li>查看用户绑定的设备列表</li></ol><h3 id="强制下线" tabindex="-1">强制下线 <a class="header-anchor" href="#强制下线" aria-label="Permalink to &quot;强制下线&quot;">​</a></h3><ol><li>在用户列表找到目标用户</li><li>点击操作列的「更多」按钮</li><li>选择「下线」</li><li>确认下线操作</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>强制下线会立即断开用户的 WebSocket 连接</p></div><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>支持批量操作多个用户：</p><ol><li>勾选需要操作的用户</li><li>在批量操作下拉框中选择操作</li><li>点击「确定」按钮</li></ol><p>支持的批量操作：</p><ul><li>批量加时</li><li>批量扣时</li><li>批量下线</li><li>批量封禁</li><li>批量解禁</li><li>批量删除</li></ul>',39)])])}const p=a(r,[["render",e]]);export{u as __pageData,p as default};
